#!/usr/bin/env node
/**
 * Copies the API's sample responses (data/sample/responses, generated by
 * `python3 scripts/make_sample_responses.py` in demo mode) into public/demo so
 * the web app renders offline with EXACTLY the shapes the back end produces.
 *
 * Everything is synthetic and labelled `"source": "synthetic-demo"`.
 * Usage: npm run fixtures:demo
 */
import { copyFileSync, existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const here = path.dirname(fileURLToPath(import.meta.url));
const source = path.resolve(here, '../../../data/sample/responses');
const outDir = path.resolve(here, '../public/demo');
mkdirSync(outDir, { recursive: true });

const files = [
  'analysis.json', 'attribution.json', 'carbon-estimate.json', 'cube.json', 'geocode.json', 'health.json',
  'market-scenario.json', 'methodologies.json', 'plot.json', 'plots.json', 'policy-eligibility.json',
  'regions.json', 'species.json', 'trees.json', 'vegetation.json', 'explain.json',
  'simulate-IN.json', 'simulate-US.json', 'simulate-EU.json', 'report.html',
];
for (const name of files) {
  const from = path.join(source, name);
  if (!existsSync(from)) {
    console.warn(`missing ${from} — run python3 scripts/make_sample_responses.py first`);
    continue;
  }
  copyFileSync(from, path.join(outDir, name));
}
// The report handle points at the HTML fixture when offline.
const meta = JSON.parse(readFileSync(path.join(source, 'report-meta.json'), 'utf8'));
meta.url = '/demo/report.html';
writeFileSync(path.join(outDir, 'report.json'), JSON.stringify(meta, null, 2) + '\n');
console.log(`copied ${files.length} fixtures to ${outDir}`);
